/**
 * dsh-image-gen - a model-facing text-to-image tool for DeepSeek Harness.
 *
 * The tool posts to an OpenAI-compatible POST /v1/images/generations endpoint and asks for
 * b64_json (through extra_body.response_format, which is what the USTC gateway honors);
 * without that flag the gateway answers with a relative URL that 404s when fetched, so the
 * base64 path is the only usable one.
 *
 * Output lands on disk: one PNG per image, named from the prompt unless a stem is given.
 * Nothing is uploaded anywhere, and no generated bytes are kept in the session log.
 * @module dsh-image-gen
 */
import { mkdir, writeFile } from 'node:fs/promises'
import { join, resolve } from 'node:path'

import z from '@deepseek-ai/schemastery'
import { defineTool } from '@deepseek-ai/dsh-tools'

export const name = 'image-gen'

/** Services this plugin needs before it can register its tool. */
export const inject = ['tools']

/** Sizes the gateway accepts today. */
const SIZES = ['1024x1024', '1024x768', '768x1024', '512x512']

/** Plugin configuration. */
export const Config = z.object({
  baseURL: z.string().required(),
  model: z.string().required(),
  apiKeyEnv: z.string().required(),
  apiKeyRef: z.string(),
  defaultSize: z.string().required(),
  maxCount: z.natural().min(1).max(8).required(),
  timeoutMs: z.natural().min(1000).max(600000).required(),
  outputDir: z.string(),
})

/**
 * Turn a prompt into a safe, short file stem.
 * @param prompt - the request text.
 * @returns a filesystem-safe stem.
 */
function stem(prompt) {
  const ascii = prompt
    .normalize('NFKD')
    .replace(/[^\p{Letter}\p{Number}]+/gu, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase()
  const trimmed = ascii.slice(0, 48).replace(/-+$/g, '')
  return trimmed === '' ? 'image' : trimmed
}

/**
 * Resolve the API key: the credential store first (that is where apiKeyEnv names live in a
 * DSH profile), then the process environment as a fallback for headless runs.
 * @param ctx - registrant context, used for the optional credentials service.
 * @param config - plugin configuration.
 * @returns the secret value.
 */
async function resolveKey(ctx, config) {
  const ref = config.apiKeyRef ?? config.apiKeyEnv
  const credentials = ctx.get?.('credentials')
  if (credentials !== undefined && typeof credentials.resolve === 'function') {
    try {
      const hit = await credentials.resolve(ref)
      if (hit !== undefined && typeof hit.value === 'string' && hit.value !== '') return hit.value
    } catch {
      // Fall through to the environment; a missing store must not fail image generation.
    }
  }
  const fromEnv = process.env[config.apiKeyEnv]
  if (typeof fromEnv === 'string' && fromEnv !== '') return fromEnv
  throw new Error(
    'image_generate: no API key. Set the credential ' + config.apiKeyEnv
      + ' (the Models page writes it) or export it in the environment.',
  )
}

/**
 * Pick the directory an image is written to: an explicit argument wins, then the plugin's
 * configured directory, then the session cwd images folder, then the process directory.
 * @param ctx - registrant context.
 * @param exec - the tool execution record.
 * @param config - plugin configuration.
 * @param explicit - the caller's output_dir, when present.
 * @returns an absolute directory path.
 */
function resolveOutDir(ctx, exec, config, explicit) {
  if (typeof explicit === 'string' && explicit.trim() !== '') return resolve(explicit.trim())
  if (typeof config.outputDir === 'string' && config.outputDir.trim() !== '') {
    return resolve(config.outputDir.trim())
  }
  const candidates = [
    exec?.agent?.session?.header?.cwd,
    exec?.agent?.session?.meta?.cwd,
    exec?.cwd,
    ctx.get?.('workingDirectory')?.current?.(),
  ]
  for (const candidate of candidates) {
    if (typeof candidate === 'string' && candidate !== '') return join(resolve(candidate), 'images')
  }
  return join(process.cwd(), 'images')
}

/**
 * Register the image_generate tool.
 * @param ctx - registrant context carrying the tool registry.
 * @param config - plugin configuration.
 * @returns when the tool is registered.
 */
export async function apply(ctx, config) {
  ctx.tools.register(defineTool({
    name: 'image_generate',
    description:
      'Generate images from a text prompt and save them as PNG files. Returns absolute paths; '
      + 'the images themselves never enter the conversation. Use it for illustrations, concept '
      + 'art, UI mockups, or any picture the user asks for. Write the prompt as a visual '
      + 'description (subject, setting, lighting, style, camera), not as a question.',
    parameters: {
      prompt: {
        type: 'string',
        required: true,
        description: 'What to draw, in English or Chinese. Be specific about subject, setting, light and style.',
      },
      count: {
        type: 'integer',
        description: 'How many images to generate (1 to ' + String(config.maxCount) + '). Defaults to 1.',
      },
      size: {
        type: 'string',
        enum: [...SIZES],
        description: 'Output size. Defaults to ' + config.defaultSize + '.',
      },
      output_dir: {
        type: 'string',
        description: 'Absolute directory for the PNG files. Defaults to the session cwd images folder.',
      },
      filename: {
        type: 'string',
        description: 'Optional file stem (without extension) for a single image.',
      },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          files: {
            type: 'array',
            required: true,
            items: {
              type: 'object',
              additionalProperties: false,
              properties: {
                path: { type: 'string', required: true },
                bytes: { type: 'integer', required: true },
              },
            },
          },
          model: { type: 'string', required: true },
          size: { type: 'string', required: true },
        },
      },
      render: (_args, value) => [{
        type: 'text',
        text: 'Generated ' + String(value.files.length) + ' image(s) with ' + value.model
          + ' at ' + value.size + ': ' + value.files.map(file => file.path).join(', '),
      }],
    },
    async execute(args, exec) {
      const count = Math.max(1, Math.min(config.maxCount, Math.trunc(args.count ?? 1)))
      const size = args.size ?? config.defaultSize
      if (!SIZES.includes(size)) throw new Error('image_generate: unsupported size ' + size)
      const key = await resolveKey(ctx, config)
      const url = config.baseURL.replace(/\/+$/, '') + '/v1/images/generations'
      const controller = new AbortController()
      const timer = setTimeout(() => controller.abort(), config.timeoutMs)
      let payload
      try {
        const response = await fetch(url, {
          method: 'POST',
          signal: controller.signal,
          headers: { authorization: 'Bearer ' + key, 'content-type': 'application/json' },
          body: JSON.stringify({
            model: config.model,
            prompt: args.prompt,
            n: count,
            size,
            extra_body: { response_format: 'b64_json' },
          }),
        })
        if (!response.ok) {
          const detail = await response.text().catch(() => '')
          throw new Error('image_generate: HTTP ' + String(response.status) + ' ' + detail.slice(0, 400))
        }
        payload = await response.json()
      } finally {
        clearTimeout(timer)
      }
      const entries = Array.isArray(payload?.data) ? payload.data : []
      if (entries.length === 0) throw new Error('image_generate: the endpoint returned no image data')
      const directory = resolveOutDir(ctx, exec, config, args.output_dir)
      await mkdir(directory, { recursive: true })
      const files = []
      for (let index = 0; index < entries.length; index += 1) {
        const base64 = entries[index]?.b64_json
        if (typeof base64 !== 'string' || base64 === '') {
          throw new Error('image_generate: the endpoint returned no b64_json for image ' + String(index + 1))
        }
        const bytes = Buffer.from(base64, 'base64')
        const explicitStem = typeof args.filename === 'string' && args.filename.trim() !== ''
        const name = explicitStem && entries.length === 1
          ? args.filename.trim().replace(/\.[A-Za-z0-9]+$/, '')
          : stem(args.prompt) + '-' + String(index + 1)
        const file = join(directory, name + '.png')
        await writeFile(file, bytes)
        files.push({ path: file, bytes: bytes.byteLength })
      }
      return { files, model: config.model, size }
    },
    presentCall: args => ({ card: 'generic', title: 'Generate image', kind: 'other', rawInput: args }),
  }))
}